'use strict';
(()=>{let pending=new URLSearchParams(location.search).get('marketing')==='1',pane=null,loading=false,active='settings';const priorAdmin=adminHTML,priorRender=render;
adminHTML=function(){if(view==='marketing')return '<div id="marketing-host"></div>';return priorAdmin();};
function assets(){if(loading)return;loading=true;if(!document.querySelector('link[href="/marketing.css"]')){const css=document.createElement('link');css.rel='stylesheet';css.href='/marketing.css';document.head.append(css);}let chain=Promise.resolve();for(const src of ['/marketing-contacts.js','/marketing-template-editor.js','/marketing-campaigns.js','/marketing.js'])chain=chain.then(()=>new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=src;script.onload=resolve;script.onerror=reject;document.body.append(script);}));chain.catch(()=>{document.querySelector('#marketing-alert').textContent='تعذر تحميل قسم التسويق. أعد تحميل الصفحة.';loading=false;});}
render=function(){if(pending&&role==='admin'){view='marketing';pending=false;}if(pane?.parentElement)pane.remove();priorRender();if(role!=='admin'||view!=='marketing')return;const host=document.querySelector('#marketing-host');if(!host)return;if(!pane){pane=document.createElement('section');pane.className='marketing-shell-pane';pane.innerHTML='<div class="page-head"><div><span class="eyebrow">أدوات التواصل</span><h1>تسويق واتساب</h1><p class="sub">مجموعات العملاء، القوالب والحملات في لوحة واحدة.</p></div><span class="marketing-status">تجربة الإدارة</span></div><div id="marketing-alert" role="status" aria-live="polite"></div><div id="marketing-app">جارٍ تحميل أدوات التسويق…</div>';}host.append(pane);const link=document.querySelector('.side-nav a[href="/marketing.html"]');if(link){link.classList.add('active');const sub=document.createElement('div');sub.className='marketing-side-sections';sub.setAttribute('aria-label','أقسام تسويق واتساب');sub.innerHTML=[['settings','link','الربط'],['contacts','users','الأرقام وجهات الاتصال'],['template','card','القوالب'],['campaign','gift','الحملات'],['test','clock','التجربة والسجل']].map(([id,ic,name])=>`<button type="button" data-marketing-section="${id}" class="${active===id?'active':''}">${icon(ic)}${name}</button>`).join('');link.after(sub);}assets();};
document.addEventListener('click',e=>{const target=e.target.closest('a[href="/marketing.html"],button[data-marketing-section],[data-action="nav"]');if(!target)return;if(target.matches('a[href="/marketing.html"]')&&role==='admin'){e.preventDefault();view='marketing';history.replaceState(null,'','/admin?marketing=1');render();}if(target.dataset.marketingSection){window.MarketingApp?.switchTab(target.dataset.marketingSection);}if(target.dataset.action==='nav'&&location.search.includes('marketing=1'))history.replaceState(null,'','/admin');});
document.addEventListener('marketing-tab',e=>{active=e.detail;document.querySelectorAll('[data-marketing-section]').forEach(b=>{b.classList.toggle('active',b.dataset.marketingSection===active);b.setAttribute('aria-current',b.dataset.marketingSection===active?'page':'false');});});render();
})();
